//tiles

let levels = [tilemap`level2`, 
tilemap`level3`,
tilemap`level4`]
startLevel(levelCurrent)
function jump(){if (player){
    if (player.isHittingTile(CollisionDirection.Bottom)) {
        player.vy = -1 * plrJUMP
        scaling.scaleToPercent(player, 110, ScaleDirection.Vertically, ScaleAnchor.Middle)
        scaling.scaleToPercent(player, 100, ScaleDirection.Horizontally, ScaleAnchor.Middle)
        pauseUntil(() => player.vy >= 0)
        player.ay = plrGRAV * 1.25
        scaling.scaleToPercent(player, 100, ScaleDirection.Vertically, ScaleAnchor.Middle)
        scaling.scaleToPercent(player, 100, ScaleDirection.Horizontally, ScaleAnchor.Middle)
        pauseUntil(() => player.isHittingTile(CollisionDirection.Bottom))

        player.ay = plrGRAV
        music.play(music.melodyPlayable(music.thump), music.PlaybackMode.InBackground)
    }}

}
function startLevel(level: number){
    sprites.destroyAllSpritesOfKind(SpriteKind.Player)
    sprites.destroyAllSpritesOfKind(SpriteKind.Food)
    sprites.destroyAllSpritesOfKind(SpriteKind.Enemy)
    sprites.destroyAllSpritesOfKind(SpriteKind.Projectile)

   player = sprites.create(assets.image`
    vex_right1
    `, SpriteKind.Player)
    plrSPD = 100
    plrGRAV = 450
    plrJUMP = 250
    scaling.scaleToPercent(player, 100, ScaleDirection.Uniformly, ScaleAnchor.Middle)
    facing = true
     let camera = sprites.create(img`
    f
`, SpriteKind.Food)

    camera.setFlag(SpriteFlag.Invisible, true)
    camera.setFlag(SpriteFlag.Ghost, true)
    camera.follow(player, 125, 400)
    scene.cameraFollowSprite(camera)
    animation.runImageAnimation(player, assets.animation`
        vex_idle_right
        `, 500, true)
    controller.moveSprite(player, plrSPD, 0)
    player.ay = plrGRAV

    let idle = true
    let right = false
    let left = false
    tiles.setCurrentTilemap(levels[level-1])
    tiles.placeOnRandomTile(player, img`
    . . . . . . . . . . . . . . . .
    . . . . 6 6 6 6 6 6 6 . . . . .
    . . 6 6 . . . . . . . 6 6 . . .
    . 6 . . . . . . . . . . . 6 . .
    . 6 . . . . . . . . . . . 6 . .
    6 . . . . . . . . . . . . . 6 .
    6 . . . . . . . . . . . . . 6 .
    6 . . . . . . . . . . . . . 6 .
    6 . . . . . . . . . . . . . 6 .
    6 . . . . . . . . . . . . . 6 .
    6 . . . . . . . . . . . . . 6 .
    6 . . . . . . . . . . . . . 6 .
    . 6 . . . . . . . . . . . 6 . .
    . 6 . . . . . . . . . . . 6 . .
    . . 6 6 . . . . . . . 6 6 . . .
    . . . . 6 6 6 6 6 6 6 . . . . .
    `)
    camera.setPosition(player.x, player.y)
    controller.A.onEvent(ControllerButtonEvent.Pressed, function on_a_pressed() {
       jump()
    })
    controller.up.onEvent(ControllerButtonEvent.Pressed, function on_a_pressed() {
        jump()

    })
    controller.B.onEvent(ControllerButtonEvent.Pressed, function on_b_pressed() {
        timer.debounce("action", 500, function () {
            if (facing) {
                player.ay = 0
                animation.stopAnimation(animation.AnimationTypes.All, player)
                controller.moveSprite(player, 0, 0)

                player.startEffect(effects.disintegrate, 500)

                player.setFlag(SpriteFlag.Invisible, true)
                player.setFlag(SpriteFlag.Ghost, true)
                player.vx = 400
                music.play(music.createSoundEffect(
                    WaveShape.Noise,
                    1395,
                    649,
                    135,
                    52,
                    500,
                    SoundExpressionEffect.Tremolo,
                    InterpolationCurve.Logarithmic
                ), music.PlaybackMode.InBackground)
                pause(200)
                controller.moveSprite(player, plrSPD, 0)
                player.setFlag(SpriteFlag.Ghost, false)
                player.setFlag(SpriteFlag.Invisible, false)
                player.vx = 0
                player.ay = plrGRAV
                animation.runImageAnimation(player, assets.animation`
                vex_idle_right
                `, 500, true)
               
                 } else if (!facing) {
                player.ay = 0
                animation.stopAnimation(animation.AnimationTypes.All, player)
                controller.moveSprite(player, 0, 0)
                player.ay = 0
                player.startEffect(effects.disintegrate, 500)

                player.setFlag(SpriteFlag.Invisible, true)
                player.setFlag(SpriteFlag.Ghost, true)
                player.vx = -400
                music.play(music.createSoundEffect(
                    WaveShape.Noise,
                    1395,
                    649,
                    135,
                    52,
                    500,
                    SoundExpressionEffect.Tremolo,
                    InterpolationCurve.Logarithmic
                ), music.PlaybackMode.InBackground)
                pause(200)
                controller.moveSprite(player, plrSPD, 0)
                player.setFlag(SpriteFlag.Ghost, false)
                player.setFlag(SpriteFlag.Invisible, false)
                player.vx = 0
                player.ay = plrGRAV
                animation.runImageAnimation(player, assets.animation`
                vex_idle_left
                `, 500, true)
            }
        })
    })

    game.onUpdate(function () {
        if (player.vx == 0 && !idle) {
            animation.stopAnimation(animation.AnimationTypes.All, player)
            idle = true
            right = false
            left = false
            if (facing) {
                animation.runImageAnimation(player, assets.animation`
                vex_idle_right
                `, 500, true)
            } else {
                animation.runImageAnimation(player, assets.animation`
                vex_idle_left
                `, 500, true)
            }

        } else if (player.vx > 0 && !right) {
            animation.stopAnimation(animation.AnimationTypes.All, player)
            idle = false
            right = true
            left = false
            facing = true
            animation.runImageAnimation(player, assets.animation`
            vex_right_walk
            `, 300, true)
        } else if (player.vx < 0 && !left) {
            animation.stopAnimation(animation.AnimationTypes.All, player)
            idle = false
            right = false
            left = true
            facing = false
            animation.runImageAnimation(player, assets.animation`
            vex_left_walk
            `, 300, true)
        }
        for (let value of tiles.getTilesByType(assets.tile`myTile13`)) {
            if (player.y + 8 <= value.top) {
                tiles.setWallAt(value, true)
            } else {
                tiles.setWallAt(value, false)
            }
        }
    })
}
   
